'use strict';
const BACKUP={snapshot:null,key:null,salt:null};
const backupB64=bytes=>{let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)};
function renderBackup(){return `<div class="content-column">${backLink('account','我的')}<h1>维护者私人备份</h1><p>保存数据库与私人原件，供独立恢复。此页仅管理员可用，备份不能放进公开网盘或网站包。</p><p class="notice">导出期间请暂停投稿和审核操作。系统会比较两次读取的摘要，变化时拒绝生成数据库包；这不是跨请求的数据库事务快照。</p><label class="form-field"><span>备份密码（至少12个字符，本站不保存）</span><input id="backup-password" type="password" minlength="12" autocomplete="new-password"></label><button class="primary" id="backup-database">读取并保存加密数据库包</button><p id="backup-status" role="status"></p><div id="backup-media-list"></div><p>原件按4MB加密分卷保存。数据库包会列出所有应有分卷；恢复工具会检查缺卷、错密码、完整大小及SHA256，不会覆盖现有库。</p><a class="button" href="tools/恢复私人备份说明.txt" download>恢复说明</a><a class="button" href="tools/restore-private.mjs" download>下载本地恢复程序</a></div>`}
async function backupHydrate(){try{await intakeAPI('backup/catalog');}catch(e){if($('backup-status'))$('backup-status').textContent=e.message}}
async function backupEncrypt(value){const iv=crypto.getRandomValues(new Uint8Array(12));const bytes=new TextEncoder().encode(JSON.stringify(value));const data=await crypto.subtle.encrypt({name:'AES-GCM',iv},BACKUP.key,bytes);return {format:'jiewangyin-private-encrypted-v1',iterations:210000,salt:backupB64(BACKUP.salt),iv:backupB64(iv),ciphertext:backupB64(new Uint8Array(data))}}
async function backupReadTables(catalog){const tables={};for(const table of catalog.tables){const rows=[];let after='';do{const d=await intakeAPI('backup/table?'+new URLSearchParams({name:table.name,after}));rows.push(...d.rows);after=d.next||'';}while(after);tables[table.name]=rows;}return tables}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.id==='backup-database'){
  const password=$('backup-password').value;if(password.length<12)throw Error('请设置至少12个字符的备份密码，并在其他安全位置保存。');b.disabled=true;
  try{const status=$('backup-status');status.textContent='正在读取私人数据库，请暂时停止写入操作…';const catalog=await intakeAPI('backup/catalog'),tables=await backupReadTables(catalog),repeat=await backupReadTables(catalog);
   const encode=v=>new TextEncoder().encode(JSON.stringify(v));if(new KanjianSHA256().update(encode(tables)).hex()!==new KanjianSHA256().update(encode(repeat)).hex())throw Error('导出期间资料发生变化，未生成数据库包。请暂停写入后重试。');
   const raw=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);BACKUP.salt=crypto.getRandomValues(new Uint8Array(16));BACKUP.key=await crypto.subtle.deriveKey({name:'PBKDF2',salt:BACKUP.salt,iterations:210000,hash:'SHA-256'},raw,{name:'AES-GCM',length:256},false,['encrypt']);
   const media=[];for(const [table,kind] of [['attachments','community'],['intake_files','intake']])for(const f of tables[table]||[]){if(!f.size||['failed','uploading'].includes(f.status))continue;const parts=[];for(let off=0,n=0;off<f.size;off+=4*1048576,n++)parts.push({name:`${kind}-${f.id}-${String(n+1).padStart(5,'0')}.encrypted.json`,offset:off,size:Math.min(4*1048576,f.size-off)});media.push({kind,id:f.id,size:f.size,storageKey:f.storage_key,sha256:f.sha256||null,parts});}
   BACKUP.snapshot={format:'kanjian-private-backup-v1',createdAt:catalog.createdAt,consistency:'two-identical-table-reads',tables,media};const payload=JSON.stringify(await backupEncrypt(BACKUP.snapshot));if(payload.length>32*1048576)throw Error('数据库包较大，请使用维护者离线备份流程。');saveBlob('私人数据库-'+Date.now()+'.encrypted.json',new Blob([payload],{type:'application/json'}));
   $('backup-media-list').innerHTML='<h2>另外保存全部原件分卷</h2>'+media.map(m=>`<p>${m.kind} · ${esc(m.id)} · ${communitySize(m.size)} · ${m.parts.length}卷 <button data-backup-media="${m.kind}/${m.id}">生成这份原件的加密分卷</button></p>`).join('');status.textContent='已请求保存加密数据库包。请另外保存下面全部原件分卷，并用恢复程序实际验收；这里只生成下载，不能确认手机已存下每份文件。';
  }finally{b.disabled=false;}
 }
 if(b.dataset.backupMedia){if(!BACKUP.key)throw Error('请先生成数据库包。');const m=BACKUP.snapshot.media.find(m=>m.kind+'/'+m.id===b.dataset.backupMedia);b.disabled=true;try{for(const part of m.parts){$('backup-status').textContent='正在生成原件分卷：'+part.name;const res=await fetch('/api/backup/media/'+m.kind+'/'+m.id,{headers:{Range:`bytes=${part.offset}-${part.offset+part.size-1}`}});if(res.status!==206)throw Error('服务器没有按范围返回原件，未生成分卷。');const bytes=new Uint8Array(await res.arrayBuffer());if(bytes.length!==part.size)throw Error('原件分卷大小不一致。');const value={format:'kanjian-private-media-part-v1',id:m.id,kind:m.kind,offset:part.offset,size:bytes.length,sha256:new KanjianSHA256().update(bytes).hex(),data:backupB64(bytes)};saveBlob(part.name,new Blob([JSON.stringify(await backupEncrypt(value))],{type:'application/json'}));}notify('已请求保存各加密分卷；请检查设备实际保存情况。')}finally{b.disabled=false;}}
 }catch(err){if($('backup-status'))$('backup-status').textContent=err.message;else notify(err.message)}});
